<script setup>
import {useForm,router} from '@inertiajs/vue3';import {ref} from 'vue';import AppLayout from '../../Layouts/AppLayout.vue';const props=defineProps({products:Object,categories:Array});const editing=ref(null);const form=useForm({name:'',category_id:'',description:'',price:0,stock:0,image:'📦'});const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);function reset(){editing.value=null;form.reset();form.clearErrors()}function edit(p){editing.value=p;form.name=p.name;form.category_id=p.category_id||'';form.description=p.description||'';form.price=p.price;form.stock=p.stock;form.image=p.image||'📦'}function save(){if(editing.value)form.put(`/admin/produk/${editing.value.id}`,{onSuccess:reset});else form.post('/admin/produk',{onSuccess:reset})}function remove(p){if(confirm(`Hapus ${p.name}?`))router.delete(`/admin/produk/${p.id}`)}
</script>
<template><AppLayout><div class="page"><div class="between"><div><h1 class="page-title">Kelola Produk</h1><p class="muted">Tambah, ubah, dan hapus produk toko.</p></div><button class="btn light" @click="reset">Tambah Produk Baru</button></div><div class="panel" style="margin:20px 0"><h3>{{editing?'Edit Produk':'Form Produk'}}</h3><form @submit.prevent="save" class="grid" style="grid-template-columns:repeat(2,1fr);gap:0 18px"><div class="field"><label>Nama produk</label><input v-model="form.name" required></div><div class="field"><label>Kategori</label><select v-model="form.category_id"><option value="">Tanpa kategori</option><option v-for="c in categories" :value="c.id">{{c.name}}</option></select></div><div class="field"><label>Harga (Rupiah)</label><input type="number" min="0" v-model="form.price" required></div><div class="field"><label>Stok</label><input type="number" min="0" v-model="form.stock" required></div><div class="field"><label>Ikon / emoji produk</label><input v-model="form.image"></div><div class="field"><label>Deskripsi</label><input v-model="form.description"></div><div class="row"><button class="btn" :disabled="form.processing">Simpan Produk</button><button type="button" class="btn light" @click="reset">Batal</button></div></form></div><div class="panel"><table class="table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><tr v-for="p in products.data" :key="p.id"><td>{{p.image}} {{p.name}}</td><td>{{p.category?.name||'-'}}</td><td>{{money(p.price)}}</td><td>{{p.stock}}</td><td><div class="row"><button class="btn light" @click="edit(p)">Edit</button><button class="btn danger" @click="remove(p)">Hapus</button></div></td></tr></tbody></table></div></div></AppLayout></template>
